SELECT id, 'B', 'reversed_relationship', $a37B$names the conjugate acid (proton gained) instead of the conjugate base (proton lost)$a37B$ FROM q
UNION ALL SELECT id, 'C', 'scale_unit_error', $a37C$removes hydrogen as a neutral atom, leaving charge at -1 instead of -2$a37C$ FROM q
