-- Q6 [Definitions & Conjugate Acid-Base Pairs · medium · Skill 4 · 5A Acid-Base Equilibria (GC, BC) · general-chemistry · ans C] (g38)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Definitions & Conjugate Acid-Base Pairs',
    $qt38$The amphiprotic dihydrogen phosphate ion, \(\text{H}_2\text{PO}_4^-\), can donate a proton in aqueous solution. What is the conjugate base produced when \(\text{H}_2\text{PO}_4^-\) acts as a Bronsted-Lowry acid?$qt38$,
    $op38$[{"label":"A","text":"\\(\\text{H}_3\\text{PO}_4\\)"},{"label":"B","text":"\\(\\text{PO}_4^{3-}\\)"},{"label":"C","text":"\\(\\text{HPO}_4^{2-}\\)"},{"label":"D","text":"\\(\\text{HPO}_4^{-}\\)"}]$op38$::jsonb,
    'C',
    $ex38$This is a General Chemistry question that falls under the content category 'Acid-Base Equilibria (GC, BC)'. The answer to this question is C because a Bronsted-Lowry acid donates exactly one proton to form its conjugate base, so removing a single \(\text{H}^+\) from \(\text{H}_2\text{PO}_4^-\) leaves \(\text{HPO}_4^{2-}\). Removing one proton subtracts one hydrogen atom (from two H to one H) and removes one positive charge from the species, so the charge becomes more negative by one unit: \(-1 \rightarrow -2\). The conjugate acid-base pair \(\text{H}_2\text{PO}_4^- / \text{HPO}_4^{2-}\) therefore differs by exactly one \(\text{H}^+\), which is the defining relationship between an acid and its conjugate base. (Choice A) \(\text{H}_3\text{PO}_4\) is the conjugate acid of \(\text{H}_2\text{PO}_4^-\); it is formed by adding a proton rather than donating one, which reverses the acid-base relationship the question asks for. (Choice B) \(\text{PO}_4^{3-}\) results from removing two protons from \(\text{H}_2\text{PO}_4^-\) (or one proton from \(\text{HPO}_4^{2-}\)); a single proton-donation step cannot strip both remaining hydrogens at once. (Choice D) \(\text{HPO}_4^-\) correctly shows the loss of one hydrogen but fails to adjust the charge, leaving it at \(-1\); donating an \(\text{H}^+\) must make the species one unit more negative, giving \(-2\), not \(-1\). Skill 4$ex38$,
    'medium', '5A', $cc38$Acid-Base Equilibria (GC, BC)$cc38$, 'general-chemistry', 4, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a38A$Names the conjugate acid (proton added) instead of the conjugate base (proton removed)$a38A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a38B$Removes two protons in a single deprotonation step, skipping the intermediate species$a38B$ FROM q
