-- Q7 [Definitions & Conjugate Acid-Base Pairs · medium · Skill 4 · 5A Acid-Base Equilibria (GC, BC) · general-chemistry · ans B] (g39)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Definitions & Conjugate Acid-Base Pairs',
    $qt39$In a solution where sulfate ion \((\text{SO}_4^{2-})\) acts as a Bronsted-Lowry base by accepting exactly one proton, what is its conjugate acid?$qt39$,
    $op39$[{"label":"A","text":"\\(\\text{SO}_3^{2-}\\)"},{"label":"B","text":"\\(\\text{HSO}_4^-\\)"},{"label":"C","text":"\\(\\text{SO}_4^{3-}\\)"},{"label":"D","text":"\\(\\text{H}_2\\text{SO}_4\\)"}]$op39$::jsonb,
    'B',
    $ex39$This is a General Chemistry question that falls under the content category 'Acid-Base Equilibria (GC, BC)'. The answer to this question is B because the conjugate acid of a Bronsted-Lowry base is the species formed when that base gains exactly one proton \((\text{H}^+)\). Adding one \(\text{H}^+\) to \(\text{SO}_4^{2-}\) adds one hydrogen and raises the charge by \(+1\): \(\text{SO}_4^{2-} + \text{H}^+ \rightarrow \text{HSO}_4^-\). The resulting hydrogen sulfate (bisulfate) ion, \(\text{HSO}_4^-\), differs from sulfate by a single \(\text{H}^+\), which is the defining feature of a conjugate acid-base pair. (Choice A) \(\text{SO}_3^{2-}\) (sulfite) is reached by removing an oxygen atom, not by adding a proton; conjugate pairs differ only by \(\text{H}^+\), and the number of oxygen atoms is unchanged. (Choice C) \(\text{SO}_4^{3-}\) keeps the same atoms but lowers the charge by \(+1\) in the wrong direction; gaining a proton must increase the charge from \(2-\) to \(1-\), not decrease it to \(3-\). (Choice D) \(\text{H}_2\text{SO}_4\) results from adding two protons to \(\text{SO}_4^{2-}\); the stem specifies acceptance of exactly one proton, so the species one step removed from sulfate is \(\text{HSO}_4^-\), with \(\text{H}_2\text{SO}_4\) being the conjugate acid of \(\text{HSO}_4^-\) rather than of \(\text{SO}_4^{2-}\). Skill 4$ex39$,
    'medium', '5A', $cc39$Acid-Base Equilibria (GC, BC)$cc39$, 'general-chemistry', 4, 110
  ) RETURNING id
)
