UNION ALL SELECT id, 'C', 'process_step_confusion', $a55C$omits square root, sets [H3O+] equal to Ka times C$a55C$ FROM q
UNION ALL SELECT id, 'D', 'scale_unit_error', $a55D$uses Kb directly as Ka without the Kw/Kb conversion$a55D$ FROM q;

-- Q24 [Salt Hydrolysis & pH of Salt Solutions · hard · Skill 2 · 5A Acid-Base Equilibria (GC, BC) · general-chemistry · ans B] (g56)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Salt Hydrolysis & pH of Salt Solutions',
    $qt56$A \(0.10\ \text{M}\) solution of sodium cyanide (\(\text{NaCN}\)) is prepared at \(25\,^\circ\text{C}\), where \(K_w = 1.0\times10^{-14}\) and the parent acid \(\text{HCN}\) has \(K_a = 4.9\times10^{-10}\). Assuming \(x\) is small relative to the initial salt concentration, what is the \(\text{pH}\) of this solution?$qt56$,
    $op56$[{"label":"A","text":"\\(\\text{pH} = 2.85\\)"},{"label":"B","text":"\\(\\text{pH} = 11.15\\)"},{"label":"C","text":"\\(\\text{pH} = 5.15\\)"},{"label":"D","text":"\\(\\text{pH} = 7.00\\)"}]$op56$::jsonb,
    'B',
    $ex56$This is a General Chemistry question that falls under the content category 'Acid-Base Equilibria (GC, BC)'. \(\text{NaCN}\) dissociates completely into \(\text{Na}^+\) (the cation of a strong base, spectator) and \(\text{CN}^-\) (the conjugate base of the weak acid \(\text{HCN}\)), so \(\text{CN}^-\) hydrolyzes water and the solution is basic. The answer to this question is B because solving the base-hydrolysis equilibrium gives \(\text{pH} = 11.15\). First convert \(K_a\) to the base ionization constant of \(\text{CN}^-\): \(K_b = \dfrac{K_w}{K_a} = \dfrac{1.0\times10^{-14}}{4.9\times10^{-10}} = 2.0\times10^{-5}\). For \(\text{CN}^- + \text{H}_2\text{O} \rightleftharpoons \text{HCN} + \text{OH}^-\), the small-\(x\) approximation gives \([\text{OH}^-] = \sqrt{K_b\,C} = \sqrt{(2.0\times10^{-5})(0.10)} = \sqrt{2.0\times10^{-6}} = 1.4\times10^{-3}\ \text{M}\). Then \(\text{pOH} = -\log(1.4\times10^{-3}) = 2.85\), so \(\text{pH} = 14.00 - 2.85 = 11.15\), consistent with a strongly basic salt of a very weak acid. (Choice A) \(2.85\) is the \(\text{pOH}\), not the \(\text{pH}\); reporting \(-\log[\text{OH}^-]\) as the \(\text{pH}\) skips the final \(\text{pH} = 14 - \text{pOH}\) conversion and wrongly labels a basic solution as strongly acidic. (Choice C) \(5.15\) results from incorrectly using \(K_a\) of \(\text{HCN}\) to compute \([\text{H}^+] = \sqrt{K_a\,C} = \sqrt{(4.9\times10^{-10})(0.10)} = 7.0\times10^{-6}\ \text{M}\); this treats the cyanide ion as a weak acid rather than as a conjugate base, ignoring that the species in solution is \(\text{CN}^-\), not \(\text{HCN}\). (Choice D) \(7.00\) assumes the salt is neutral, which would be true only for the salt of a strong acid and strong base; it overlooks that \(\text{CN}^-\) derives from the weak acid \(\text{HCN}\) and therefore hydrolyzes to raise the \(\text{pH}\). Skill 2$ex56$,
    'hard', '5A', $cc56$Acid-Base Equilibria (GC, BC)$cc56$, 'general-chemistry', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
